wrong_code.class:
// Security flaw: public static final array is MUTABLE!
// Callers can modify the elements of the array directly.
public class SecurityConstants {
    // POTENTIAL SECURITY HOLE!
    public static final String[] PRIVILEGED_ROLES = {
        "ADMIN", "SUPERUSER", "OPERATOR"
    };
}

wrong_code.call_site:
public class Main {
    public static void main(String[] args) {
        // Malicious client or buggy code mutates the 'constant' array:
        SecurityConstants.PRIVILEGED_ROLES[0] = "GUEST";
        // Now GUEST is treated as an ADMIN throughout the system!
    }
}

right_code.class:
// Safe alternative 1: Private array + public unmodifiable List
// Safe alternative 2: Private array + clone() accessor
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class SecurityConstants {
    private static final String[] PRIVATE_ROLES = {
        "ADMIN", "SUPERUSER", "OPERATOR"
    };

    // Solution 1: Public unmodifiable List
    public static final List<String> PRIVILEGED_ROLES =
        Collections.unmodifiableList(Arrays.asList(PRIVATE_ROLES));

    // Solution 2: Public method returning defensive copy
    public static final String[] getRoles() {
        return PRIVATE_ROLES.clone();
    }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        // Attempting to modify throws UnsupportedOperationException:
        // SecurityConstants.PRIVILEGED_ROLES.set(0, "GUEST");

        // Or with array clone, modifying the clone does not affect the original:
        String[] roles = SecurityConstants.getRoles();
        roles[0] = "GUEST";
        System.out.println(SecurityConstants.PRIVILEGED_ROLES.get(0)); // Still "ADMIN"!
    }
}
